"""Tiny grader for the study group."""
import json, sys


def load_submission(path):
    with open(path) as f:
        return json.load(f)


def score(submission):
    total = 0
    for answer in submission["answers"]:
        if answer.get("correct"):
            total += answer.get("points", 1)
    return total


def letter(score, out_of):
    ratio = score / out_of if out_of else 0
    if ratio >= 0.9:
        return "A"
    if ratio >= 0.8:
        return "B"
    if ratio >= 0.7:
        return "C"
    if ratio >= 0.6:
        return "D"
    return "F"


def main(path):
    sub = load_submission(path)
    s = score(sub)
    out_of = sum(a.get("points", 1) for a in sub["answers"])
    print(f"{sub.get('name','?')}: {s}/{out_of} ({letter(s, out_of)})")


if __name__ == "__main__":
    main(sys.argv[1])

import unittest

from grader import score, letter


class GraderTests(unittest.TestCase):
    def test_score_sums_correct_points(self):
        sub = {
            "answers": [
                {"correct": True, "points": 2},
                {"correct": False, "points": 3},
                {"correct": True, "points": 5},
            ]
        }
        self.assertEqual(score(sub), 7)

    def test_letter_a(self):
        self.assertEqual(letter(9, 10), "A")

    def test_letter_f(self):
        self.assertEqual(letter(4, 10), "F")


if __name__ == "__main__":
    unittest.main()

